CREATE TABLE IF NOT EXISTS person_profiles (person_id BIGINT UNSIGNED PRIMARY KEY,nationality VARCHAR(80) NULL,birth_city VARCHAR(120) NULL,gender VARCHAR(40) NULL,primary_position VARCHAR(60) NULL,secondary_positions JSON NULL,dominant_foot VARCHAR(20) NULL,preferred_number TINYINT UNSIGNED NULL,height_cm SMALLINT UNSIGNED NULL,weight_kg DECIMAL(5,2) NULL,address TEXT NULL,emergency_contact_name VARCHAR(160) NULL,emergency_contact_phone VARCHAR(40) NULL,photo_path VARCHAR(255) NULL,notes TEXT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_guardians (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id BIGINT UNSIGNED NOT NULL,full_name VARCHAR(180) NOT NULL,document_number VARCHAR(120) NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,relationship_type VARCHAR(80) NOT NULL,authorizations_json JSON NULL,terms_accepted_at DATETIME NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(person_id) REFERENCES people(id),INDEX(person_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS document_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,applies_to VARCHAR(30) NOT NULL DEFAULT 'athlete',required_for_registration TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS person_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id BIGINT UNSIGNED NOT NULL,document_type_id BIGINT UNSIGNED NULL,document_number_hash CHAR(64) NULL,file_path VARCHAR(255) NULL,expires_at DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',review_reason TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(person_id) REFERENCES people(id),FOREIGN KEY(document_type_id) REFERENCES document_types(id),FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE KEY document_duplicate(document_type_id,document_number_hash),INDEX(person_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS team_membership_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,tournament_id BIGINT UNSIGNED NULL,starts_at DATE NOT NULL,ends_at DATE NULL,reason TEXT NULL,source VARCHAR(80) NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,FOREIGN KEY(person_id) REFERENCES people(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(person_id,tournament_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE registrations ADD COLUMN rejection_reason TEXT NULL AFTER status, ADD COLUMN submitted_at DATETIME NULL AFTER rejection_reason, ADD COLUMN reviewed_at DATETIME NULL AFTER submitted_at, ADD COLUMN reviewed_by BIGINT UNSIGNED NULL AFTER reviewed_at, ADD FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL;
